parameters.jsCode:
// Validate incoming data
const data = $input.first().json;

console.log('📬 Received status change notification:', JSON.stringify(data, null, 2));

if (!data.taskId || !data.newStatus || !data.oldStatus) {
  throw new Error('Missing required fields: taskId, newStatus, or oldStatus');
}

if (!data.creatorEmail) {
  console.log('⚠️ No creatorEmail provided, skipping notification');
  return [];
}

// Status-Namen formatieren (Deutsch)
const statusNames = {
  'triage': 'Triage',
  'todo': 'To Do',
  'in-progress': 'In Bearbeitung',
  'await-feedback': 'Feedback abwarten',
  'done': 'Erledigt'
};

// Status-Emojis
const statusEmojis = {
  'triage': '🔍',
  'todo': '📋',
  'in-progress': '⚙️',
  'await-feedback': '⏳',
  'done': '✅'
};

const oldStatusFormatted = statusNames[data.oldStatus] || data.oldStatus;
const newStatusFormatted = statusNames[data.newStatus] || data.newStatus;
const statusEmoji = statusEmojis[data.newStatus] || '🔔';

console.log('✅ Formatted status change:', {
  from: oldStatusFormatted,
  to: newStatusFormatted,
  emoji: statusEmoji
});

return {
  json: {
    taskId: data.taskId,
    taskTitle: data.taskTitle || 'Untitled Task',
    oldStatus: oldStatusFormatted,
    newStatus: newStatusFormatted,
    statusEmoji: statusEmoji,
    creatorEmail: data.creatorEmail,
    creatorName: data.creatorName || 'User',
    updatedBy: data.updatedBy || 'Team Member',
    timestamp: new Date().toISOString(),
    formattedDate: new Date().toLocaleString('de-DE')
  }
};

